/* TEST-ONLY: the Q2.14 biquad (HB[24]) with the rounding add removed from q2_14_mul_round, i.e. a truncating version of the same
 * section, used as the reference for the accuracy comparison on the -1.9556 example.  Generated by textual substitution from the listing;
 * every public name is suffixed _trunc.  Needs Q2_14_SHIFT / q15_wide_add_sat from hb_biquad_q15.h / hb_qformat.h. */
#ifndef HBA_BIQUAD_Q15_TRUNC_H
#define HBA_BIQUAD_Q15_TRUNC_H
#include "hb_biquad_q15.h"

static inline int32_t q2_14_mul_trunc(int32_t coeff_q2_14, int32_t sample_q15) {
    int64_t product = (int64_t)coeff_q2_14 * sample_q15;
    return (int32_t)(product >> Q2_14_SHIFT   /* TEST-ONLY: rounding add removed */);
}

typedef struct {
    int16_t b0, b1, b2;   // feedforward coeffs, Q2.14 (not Q1.15 - see above)
    int16_t a1, a2;       // feedback coeffs, Q2.14, a0 normalized to 1 (same convention as the
                           // float biquad_t)
    q15_wide_t z1, z2;    // state (Direct Form II Transposed), kept in the SAME wide container
                           // Chapter 1 defines for exactly this reason: a resonant section's
                           // internal state can transiently run past the nominal +-1.0 signal
                           // range even when the final output never does, and narrowing at every
                           // intermediate step (rather than once, at the true output) would clip
                           // headroom Direct Form II Transposed exists to provide.
} biquad_q15_trunc_t;

static int16_t biquad_process_q15_trunc(biquad_q15_trunc_t *bq, int16_t input) {
    int32_t out_wide = q15_wide_add_sat(q2_14_mul_trunc(bq->b0, input), bq->z1);
    int16_t output;
    if (out_wide > 32767) output = 32767;
    else if (out_wide < -32768) output = -32768;
    else output = (int16_t)out_wide;

    bq->z1 = q15_wide_add_sat(q2_14_mul_trunc(bq->b1, input) - q2_14_mul_trunc(bq->a1, output), bq->z2);
    bq->z2 = q2_14_mul_trunc(bq->b2, input) - q2_14_mul_trunc(bq->a2, output);

    return output;
}
#endif
